// Script local de seed — desabilita verificação TLS para funcionar atrás de proxy corporativo
process.env.NODE_TLS_REJECT_UNAUTHORIZED = '0';

const SURL = 'https://fugztekwkpmambvcyrmm.supabase.co';
const SK = process.env.SUPABASE_SERVICE_ROLE;  // export SUPABASE_SERVICE_ROLE=seu_token
const PAT = process.env.SUPABASE_PAT;          // export SUPABASE_PAT=seu_token
const REF = 'fugztekwkpmambvcyrmm';
const H = {
  apikey: SK,
  Authorization: `Bearer ${SK}`,
  'Content-Type': 'application/json',
  Prefer: 'return=minimal',
};

async function doSQL(q) {
  const r = await fetch(`https://api.supabase.com/v1/projects/${REF}/database/query`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${PAT}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ query: q }),
  });
  const t = await r.text();
  if (!r.ok) throw new Error(`SQL ${r.status}: ${t}`);
  return t;
}

async function doREST(method, path, body) {
  const r = await fetch(`${SURL}/rest/v1/${path}`, {
    method,
    headers: H,
    body: body != null ? JSON.stringify(body) : undefined,
  });
  if (!r.ok) {
    const t = await r.text();
    throw new Error(`REST ${method} ${path} ${r.status}: ${t}`);
  }
}

