async function main() {
  console.log('Adicionando colunas se necessário...');
  try {
    await doSQL('ALTER TABLE exercise_library ADD COLUMN IF NOT EXISTS steps jsonb, ADD COLUMN IF NOT EXISTS form_tips jsonb, ADD COLUMN IF NOT EXISTS common_mistakes jsonb, ADD COLUMN IF NOT EXISTS variations jsonb, ADD COLUMN IF NOT EXISTS substitutes jsonb, ADD COLUMN IF NOT EXISTS animation_url text');
    console.log('Colunas OK.');
  } catch (e) { console.warn('Colunas (ok se já existirem):', e.message); }

  console.log('Limpando tabela...');
  await doSQL('DELETE FROM exercise_library');
  console.log('Tabela limpa.');

  let total = 0;
  for (let i = 0; i < EX.length; i += 20) {
    const batch = EX.slice(i, i + 20);
    await doREST('POST', 'exercise_library', batch);
    total += batch.length;
    console.log(`Inseridos: ${total}/${EX.length}`);
  }
  console.log(`\n✓ ${total} exercícios inseridos com sucesso!`);
}

main().catch(e => { console.error('ERRO FATAL:', e.message); process.exit(1); });
